abstract class KitchenTool {private int speedLevel=1;public abstract String prepare();public int getSpeedLevel(){return speedLevel;}public void setSpeedLevel(int s){if(s>=1&&s<=5)speedLevel=s;else System.out.println("Invalid speed level. Value rejected.");}}
interface Washable {String clean();}
class Blender extends KitchenTool implements Washable {public Blender(){super();}public String prepare(){return "Blending at speed "+getSpeedLevel();}public String clean(){return "Blender rinsed and dried";}}
public class SmartKitchen {public static void main(String[] args){Blender b=new Blender();b.setSpeedLevel(3);System.out.println(b.getSpeedLevel());b.setSpeedLevel(9);System.out.println(b.getSpeedLevel());System.out.println(b.prepare());System.out.println(b.clean());}}